  rect: (options) => ({ kind: "rect", ...opts(options) }),
  path: (options) => ({ kind: "path", ...opts(options) }),
  media: (options) => ({ kind: "media", ...opts(options) }),
  adjustment: (options) => ({ kind: "adjustment", ...opts(options) }),
  group: (options, children) => ({ kind: "group", ...opts(options), children: kids(children) }),
  column: (options, children) => ({ kind: "column", ...opts(options), children: kids(children) }),
  row: (options, children) => ({ kind: "row", ...opts(options), children: kids(children) }),
  sequence: (options, children) => ({ kind: "sequence", ...opts(options), children: kids(children) }),
